# Concrete budgets B (per-solve bits, free parameter; no rho used) exhibiting the smallest misplacements.
import importlib.util, io, contextlib, json
spec = importlib.util.spec_from_file_location("rc", "review_calcs.py")
rc = importlib.util.module_from_spec(spec)
with contextlib.redirect_stdout(io.StringIO()):
    spec.loader.exec_module(rc)
def table(fs, Ds):
    return {name: {D: round(f(D), 4) for D in Ds} for name, f in fs.items()}
def find_example(fref, falt, dref_target, gap=2, Dmax=64):
    vals = sorted(set([fref(D) for D in range(2, Dmax + 1)] + [falt(D) for D in range(2, Dmax + 1)]))
    for i in range(len(vals) - 1):
        B = (vals[i] + vals[i + 1]) / 2
        dr, da = rc.dstar(fref, B), rc.dstar(falt, B)
        if dr == dref_target and abs(da - dr) >= gap:
            return {"B": round(B, 4), "D*_ref": dr, "D*_alt": da}
    return None
out = {}
# (a) normaliser held at g(4): toy n = 8, omega 3
out["a_normaliser_toy_n8_w3"] = {"values": table({"R-B": rc.ext_RB(8, 3.0), "R-M": rc.ext_RM(8, 3.0)}, range(4, 9)),
                                "example": find_example(rc.ext_RB(8, 3.0), rc.ext_RM(8, 3.0), 5)}
# (a') same at n = 571
out["a_normaliser_n571_w3"] = {"example": find_example(rc.ext_RB(571, 3.0), rc.ext_RM(571, 3.0), 7)}
# (b) LA exponent held at omega = 3 vs falling to 2 above D = 4, n = 571 (reference R-M)
out["b_LA_exponent_n571_w3"] = {"values": table({"R-M": rc.ext_RM(571, 3.0), "S_sp(M)": rc.ext_spM(571, 3.0)}, range(4, 10)),
                                "example": find_example(rc.ext_RM(571, 3.0), rc.ext_spM(571, 3.0), 6)}
# (c) block exponent held at block size n vs F4 count n(m*-1) above D = 4, n = 571, m* = 12 (reference R-B)
out["c_block_exponent_n571_w3"] = {"values": table({"R-B": rc.ext_RB(571, 3.0), "S_hyb": rc.ext_hyb(571, 3.0, 12)}, range(4, 13)),
                                   "example": find_example(rc.ext_RB(571, 3.0), rc.ext_hyb(571, 3.0, 12), 9)}
print(json.dumps(out, indent=1))
